import { isLive } from "@/lib/soft-delete";
import type { UserId } from "@/types/common";
import type { Member } from "@/types/member";

/**
 * Membership predicates.
 *
 * A membership row outlives the membership: removal archives it so the audit
 * log keeps pointing at a real row, and `status` keeps recording what the
 * membership was. "Is this person in the workspace right now?" therefore needs
 * both columns, and this module is the one place that combines them.
 */

/** True when the row is a live, active membership — a current member. */
export function isCurrentMember(
  member: Member | null | undefined,
): member is Member {
  return (
    member !== null &&
    member !== undefined &&
    member.status === "active" &&
    isLive(member)
  );
}

/**
 * Raised when work would be handed to someone who is not a current member of
 * the organization — a former member, an unaccepted invitee or a stranger.
 */
export class NotAMemberError extends Error {
  readonly code = "validation_failed" as const;

  constructor(
    readonly field: string,
    readonly userId: UserId,
  ) {
    super(`User ${userId} is not a member of this organization.`);
    this.name = "NotAMemberError";
  }
}

