 * Throws unless `userId` is a current member of `orgId`. Guards every write
 * that hands work to a person — an assignee, a project lead — so nothing is
 * given to someone who has left or never joined. `field` names the input the
 * user id came from, for the form error.
 */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
  field: string,
