import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
const ROOT = "/private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4cf7f0a3-d457-4399-9c90-cf01be6fca65";
import { emit, subscribe } from "@/lib/event-bus";
