import * as notificationRepo from "@/server/repositories/notification-repository";
import * as memberService from "@/server/services/member-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import * as commentService from "@/server/services/comment-service";
import * as sessionService from "@/server/services/session-service";
import { listDigestRecipients } from "@/server/services/digest-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";

vi.mock("@/lib/rate-limit", async () => (await import(ROOT + "/tests/server/_support/doubles/misc")).rateLimitModule);

const fx = await import(ROOT + "/tests/server/_support/fixtures");

let cleanup: () => void;
beforeAll(async () => { cleanup = await fx.useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

async function unread(orgId: any, userId: any) {
  return (await notificationRepo.listNotifications({ orgId, recipientId: userId, unreadOnly: false, limit: 100, cursor: null } as any)).items;
}

describe("removed members", () => {
  it("covers the reports", async () => {
    const t = await fx.createTenant("rm-a", "growth");
    const other = await fx.createTenant("rm-b", "growth");
    const memberUser = t.userIds.member;
    // same user also in other org
    await memberRepo.insertMember(other.org.id, memberUser, "member", null);
    await usageRepo.recomputeUsage(t.org.id);

    const issue = await issueService.createIssue(t.actors.member, fx.issueInput(t.org.id, t.project.id, { title: "By member", assigneeId: memberUser, dueAt: "2020-01-01T00:00:00.000Z" }));
    const otherIssue = await issueService.createIssue(other.actors.owner, fx.issueInput(other.org.id, other.project.id, { title: "Other", assigneeId: memberUser }));
    const led = await projectService.createProject(t.actors.owner, { orgId: t.org.id, name: "Led", slug: "led", key: "LED", description: null, visibility: "org", leadId: memberUser, color: "#6366f1", targetDate: null } as any);
    await preferenceRepo.upsertPreference({ orgId: t.org.id, userId: memberUser, kind: "comment_created", inApp: true, email: true, digestOnly: true });
    expect(await listDigestRecipients(t.org.id)).toContain(memberUser);

    const seatsBefore = await memberRepo.countActiveMembers(t.org.id);
    const usageBefore = (await usageRepo.getUsage(t.org.id)).seatsUsed;
    const m = (await memberRepo.findMember(t.org.id, memberUser))!;
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m.id });

    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(seatsBefore - 1);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(usageBefore - 1);
    // 1. cannot act
    expect(await memberService.resolveActor(memberUser, t.org.id)).toBeNull();
    const principal = { userId: memberUser, email: "x", activeOrgId: t.org.id, expiresAt: "2099-01-01T00:00:00.000Z" } as any;
    expect(await sessionService.resolveActorForOrg(principal, "rm-a")).toBeNull();
    await expect(sessionService.switchActiveOrg(principal, { orgId: t.org.id } as any)).rejects.toThrow();
    // other org untouched
    expect(await sessionService.resolveActorForOrg(principal, "rm-b")).not.toBeNull();
    expect((await issueRepo.findIssueById(other.org.id, otherIssue.id))!.assigneeId).toBe(memberUser);

    // 4. unassigned / no lead
    expect((await issueRepo.findIssueById(t.org.id, issue.id))!.assigneeId).toBeNull();
    expect((await projectRepo.findProjectById(t.org.id, led.id))!.leadId).toBeNull();
    await expect(issueService.assignIssue(t.actors.owner, { orgId: t.org.id, issueId: issue.id, assigneeId: memberUser })).rejects.toThrow(/not a member/);
    expect((await issueRepo.findIssueById(t.org.id, issue.id))!.assigneeId).toBeNull();
    const countBefore = await issueRepo.countIssues(t.org.id, t.project.id);
    await expect(issueService.createIssue(t.actors.owner, fx.issueInput(t.org.id, t.project.id, { assigneeId: memberUser }))).rejects.toThrow();
    expect(await issueRepo.countIssues(t.org.id, t.project.id)).toBe(countBefore);
    const pc = await projectRepo.countProjects(t.org.id);
    await expect(projectService.createProject(t.actors.owner, { orgId: t.org.id, name: "Nope", slug: "nope", key: "NOP", description: null, visibility: "org", leadId: memberUser, color: "#6366f1", targetDate: null } as any)).rejects.toThrow();
    expect(await projectRepo.countProjects(t.org.id)).toBe(pc);
    await expect(projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: led.id, leadId: memberUser })).rejects.toThrow();
    try { await projectService.updateProject(t.actors.owner, { orgId: t.org.id, projectId: led.id, leadId: memberUser }); } catch (e) { console.log(toAppError(e)); }

    // 3. notifications
    const before = (await unread(t.org.id, memberUser)).length;
    // they authored `issue`; someone comments
    await commentService.createComment(t.actors.owner, { orgId: t.org.id, issueId: issue.id, body: "hi @member", parentId: null, mentionedUserIds: [memberUser] } as any);
    await emit("issue.overdue", { orgId: t.org.id, actorId: null, occurredAt: "2026-01-01T00:00:00.000Z" as any, issueId: issue.id, projectId: issue.projectId, dueAt: "2020-01-01T00:00:00.000Z" as any, assigneeId: memberUser });
    await emit("comment.created", { orgId: t.org.id, actorId: t.userIds.owner, occurredAt: "2026-01-01T00:00:00.000Z" as any, commentId: "c1" as any, issueId: issue.id, mentionedUserIds: [memberUser] });
    await runOverdueIssueJob(new Date());
    expect((await unread(t.org.id, memberUser)).length).toBe(before);
    expect(await listDigestRecipients(t.org.id)).not.toContain(memberUser);

    // 5. conflict
    for (const call of [
      () => memberService.updateMemberRole(t.actors.owner, { orgId: t.org.id, memberId: m.id, role: "admin" }),
      () => memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: m.id }),
    ]) {
      let err: unknown; try { await call(); } catch (e) { err = e; }
      expect(toAppError(err).code).toBe("conflict");
    }
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(seatsBefore - 1);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(usageBefore - 1);

    // 2. re-invite
    const token = "r".repeat(32);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "member@rm-a.test", role: "viewer", expiresInDays: 14 }, t.userIds.admin, hashToken(token));
    const back = await invitationService.acceptInvitation(memberUser, { token });
    expect(back.id).toBe(m.id);
    expect(back.archivedAt).toBeNull();
    expect(back.role).toBe("viewer");
    expect(back.invitedBy).toBe(t.userIds.admin);
    expect(back.createdAt).toBe(m.createdAt);
    const inv = await invitationRepo.findInvitationByTokenHash(hashToken(token));
    expect(back.joinedAt).toBe(inv!.acceptedAt);
    expect(await memberRepo.countActiveMembers(t.org.id)).toBe(seatsBefore);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(usageBefore);
    const listed = await memberRepo.listMembers({ orgId: t.org.id, limit: 100, cursor: null } as any);
    expect(listed.items.filter((x) => x.userId === memberUser)).toHaveLength(1);
    expect(await sessionService.resolveActorForOrg(principal, "rm-a")).toMatchObject({ role: "viewer" });
    await expect(invitationService.acceptInvitation(memberUser, { token })).rejects.toThrow(/already/);
    await emit("issue.assigned", { orgId: t.org.id, actorId: t.userIds.owner, occurredAt: "2026-01-01T00:00:00.000Z" as any, issueId: issue.id, projectId: issue.projectId, previousAssigneeId: null, assigneeId: memberUser });
    expect((await unread(t.org.id, memberUser)).length).toBe(before + 1);
    expect(await listDigestRecipients(t.org.id)).toContain(memberUser);

    // current member accepts
    const token2 = "s".repeat(32);
    await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "admin@rm-a.test", role: "viewer", expiresInDays: 14 }, t.userIds.owner, hashToken(token2));
    const pending = await invitationRepo.countPendingInvitations(t.org.id);
    const adminBefore = await memberRepo.findMember(t.org.id, t.userIds.admin);
    const u = (await usageRepo.getUsage(t.org.id)).seatsUsed;
    const same = await invitationService.acceptInvitation(t.userIds.admin, { token: token2 });
    expect(same).toEqual(adminBefore);
    expect(await memberRepo.findMember(t.org.id, t.userIds.admin)).toEqual(adminBefore);
    expect((await usageRepo.getUsage(t.org.id)).seatsUsed).toBe(u);
    expect(await invitationRepo.countPendingInvitations(t.org.id)).toBe(pending - 1);
    await expect(invitationService.acceptInvitation(t.userIds.admin, { token: token2 })).rejects.toThrow(/already/);
  });
