/**
 * Accepting runs unauthenticated: the token is the credential, so there is no
 * `Actor` to scope against and every check has to come off the stored row.
 *
 * An invitation is used up by being accepted, whoever accepts it. What the
 * acceptance does to the membership depends on the row the org already has
 * for this user:
 *  - none: a new membership is created;
 *  - a former member's (archived) row, or one still marked `invited`: that
 *    same row is re-admitted — active again, with the invitation's role and
 *    inviter and the acceptance time as its join date;
 *  - a current member's row: nothing about it changes, no seat is taken and
 *    no `member.joined` is published.
 */
export async function acceptInvitation(
  userId: UserId,
  input: AcceptInvitationTokenInput,
): Promise<Member> {
  const invitation = requireFound(
    await invitationRepo.findInvitationByTokenHash(hashToken(input.token)),
    "Invitation",
    "token",
  );

  if (invitation.revokedAt !== null) {
    throw new Error("That invitation has been revoked");
  }
  if (invitation.acceptedAt !== null) {
    throw new Error("That invitation has already been accepted");
  }

  const acceptedAt = toIsoTimestamp(new Date());
  if (invitation.expiresAt <= acceptedAt) {
    throw new Error("That invitation has expired");
  }

  const existing = await memberRepo.findMember(invitation.orgId, userId);

  // Claim the invitation before touching the membership, so a second accept
  // racing this one cannot admit anybody.
  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    acceptedAt,
  );

  if (existing && isLive(existing) && existing.status !== "invited") {
    return existing;
  }

  const member = existing
    ? await memberRepo.reinstateMember(
        invitation.orgId,
        existing.id,
        invitation.role,
        invitation.invitedBy,
        acceptedAt,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
        acceptedAt,
      );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

